try{const raw=localStorage.getItem(KEY);if(raw){const x=JSON.parse(raw);if(E.validate(E.upgrade(x))){s=x;ui.started=true;}}if(!ui.started){const old=localStorage.getItem('touchline-life-v1');if(old){const x=JSON.parse(old);if(x.v===1&&x.attrs&&typeof x.name==='string')legacy=x;}}}catch{}
