const crest=(id,z=36)=>{const c=E.getClub(id),src=window.CHINA_CLUB_CRESTS?.[c?.mediaId]||CRESTS[id];return src?`<img class="crest" src="${src}" width="${z}" height="${z}" alt="${esc(name(c))}队徽" loading="lazy">`:`<span class="crest-fallback" style="width:${z}px;height:${z}px" title="未收录真实队徽">${icon('shield',Math.max(14,z*.45))}</span>`;};
const bar=(label,value,color)=>`<div class="statbar"><div class="barlabel"><span>${label}</span><span>${Math.round(value)} <small class="muted">/ 100</small></span></div><div class="bar"><i style="width:${E.clamp(value)}%;${color?'background:'+color:''}"></i></div></div>`;
