function footer(){return `<footer class="footer"><div class="footer-items"><span><strong>${n(D.meta.clubs)}</strong> 家俱乐部</span><span><strong>${n(D.meta.players)}</strong> 名真实球员</span><span><strong>${n(crestCount())}</strong> 个真实队徽</span><span><strong>${n(Object.keys(window.PLAYER_PORTRAITS||{}).length)}</strong> 张球员照片</span></div><button class="textbtn footer-end" data-action="about">中国联赛 · 2026 资料更新 ${icon('info',12)}</button></footer>`;}
function renderV3(){const page=navs.find(x=>x[0]===ui.page),club=E.activeClub(s),offers=s.offers.filter(o=>o.status==='active'&&o.expires>=s.step);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">${icon('ball',26)}</span><div><strong>逐梦绿茵</strong><small>STADIUM · 4.0</small></div></div><div class="side-label">YOUR CAREER, YOUR DECISIONS</div><nav class="nav" aria-label="主导航">${navs.map(([id,i,t])=>`<button data-nav="${id}" class="${ui.page===id?'active':''}">${icon(i)}${t}${id==='contracts'&&offers.length?`<span class="notice">${offers.length}</span>`:''}</button>`).join('')}</nav><div class="side-player"><strong>${esc(s.name)} <span style="color:#a3bd8c;font-size:10px;margin-left:5px">${s.pos}</span></strong><small>${s.age} 岁 · ${E.stage(s).n}<br>${esc(club?name(club):s.age<9?'校园与社区':'寻找下一站')}</small><div class="loyalty-track"><i style="width:${(s.age-7)/33*100}%"></i></div><small style="font-size:8px">YOUR LIFE BEYOND THE TOUCHLINE</small></div><div class="side-bottom"><div class="side-status"><i class="dot"></i>${ui.started?'本地自动存档已启用':'从第一片球场开始'}</div><div class="side-actions"><button data-action="export">导出存档</button><button data-action="import">导入存档</button><button data-action="new">新生涯</button></div><button class="side-link" data-action="about">规则、数据与图标来源 ${icon('arrow',11)}</button></div></aside><main class="main"><header class="topbar"><div class="top-breadcrumb">球员生涯 ${icon('chevron',11)} <strong>${page[2]}</strong></div><div class="mobile-brand">${icon('ball',22)} 逐梦绿茵</div><div class="top-actions"><span class="desktop-date">${E.date(s)}</span><span class="pill ${E.marketOpen(s)?'green':''}"><i class="dot"></i>${E.marketOpen(s)?'注册窗口开放':'注册窗口关闭'}</span><button class="textbtn" data-action="about" aria-label="游戏说明">${icon('info',16)}</button><button class="top-avatar" data-action="player" aria-label="球员资料">${esc(s.name[0])}</button></div></header><div class="page">${content()}${footer()}</div></main><nav class="mobile-nav" aria-label="移动导航">${navs.filter(x=>['hub','development','contracts','competition','archive'].includes(x[0])).map(([id,i,t,m])=>`<button data-nav="${id}" class="${ui.page===id?'active':''}">${icon(i,19)}${m}</button>`).join('')}<button data-v4="more">${icon('team',19)}更多</button></nav></div><input id="import-file" class="file-input" type="file" accept=".json,application/json">`;}
