function passport(){const c=E.activeClub(s);return `<section class="profile"><div class="passport-head"><div class="eyebrow">PLAYER PASSPORT</div><div class="rating-number">${E.rating(s)}<small>综合能力</small></div>${shirt()}</div><div class="passport-body"><div class="passport-name">${esc(s.name)} <span class="badge">${E.positions[s.pos]}</span></div><div class="passport-sub">${cn(s.nation)} · ${s.age} 岁 · ${s.foot==='left'?'左脚':s.foot==='both'?'双脚':'右脚'} · ${s.retired?'已退役':E.competitionContext(s).label}</div><div class="divider"></div><div class="profile-club">${c?crest(c.id,37):`<span class="crest-fallback">${icon('ball',20)}</span>`}<div class="club-title"><strong>${esc(c?name(c):'校园与社区足球')}</strong><small>${E.competitionContext(s).label} · ${s.loan?'租借效力 · 母队 '+esc(name(E.getClub(s.clubId))):s.contract?E.roles[s.contract.role]+' · '+(s.contract.kind==='academy'?'青年培养协议':'职业合同'):'尚未签约俱乐部'}</small></div></div><div class="divider"></div><div class="body-mini"><div><b>${s.body.h}<small> cm</small></b><span>身高</span></div><div><b>${s.body.w}<small> kg</small></b><span>体重</span></div><div><b>${s.age}</b><span>年龄</span></div></div><div class="divider"></div>${bar('身体健康',s.health)}${bar('疲劳负荷',s.fatigue,'#bda96f')}${bar('教练信任',s.coach,'#8fa78c')}<div class="profile-line"><span>个人储蓄</span><strong>${cash(s.cash)}</strong></div><div class="profile-line"><span>周薪 · 税前</span><strong>${cash(s.contract?.wage||0)}</strong></div><button class="btn outline small" style="width:100%;margin-top:10px" data-action="player">完整球员档案 ${icon('arrow',12)}</button></div></section>`;}
