 modal(`${mh(esc(name(c))+' · 这份邀请意味着什么',`${a.tierName} · ${a.role} · 选择后按约定发展`)}<div class="offer-title">${crest(c.id,58)}<div><strong>${esc(name(c))}</strong><small>${esc(o.reason||'双方就合作方向达成了初步意向。')}</small></div></div><div class="detail-grid">${[[a.wageLabel,t.wage?cash(t.wage)+'/周':'无职业工资 · 培养支持'],[o.kind==='loan'?'租借期限':'合同期限',o.kind==='loan'?t.duration*3+' 个月':t.years+' 年'],['开始效力的队伍',a.tierName],['许诺角色',a.role],['同级比赛机会参考',a.minutesLow+'–'+a.minutesHigh+'%'],['一线队出场参考',a.firstChance+'%'],['签字费',o.kind==='loan'?'不重复支付':cash(t.signingBonus)],['一线队出场 / 进球奖金',cash(t.appBonus)+' / '+cash(t.goalBonus)],['解约金 / 买断费',cash(o.kind==='loan'?t.buyout:t.release)],['俱乐部间转会费',cash(o.transferFee||0)]].map(([k,v])=>`<div><small>${k}</small>${esc(v)}</div>`).join('')}</div><div class="v3-outlook-panel"><h3>优势与代价</h3><p class="good">${esc(a.pros.join('；'))}</p><p class="bad">${esc(a.cons.join('；'))}</p><h3>俱乐部提出的发展路径</h3><p>${esc(a.plan)}</p><h3>给你的建议</h3><p>${esc(a.advice)}</p></div><div class="banner-note">${o.kind==='loan'?'租借保留母队合同，薪资不会重复支付。租满回归，提前召回或买断需再协商。':'角色承诺会影响比赛机会，但伤病、状态和竞争可能让实际出场不同。'} ${a.tier!=='first'?'这些比赛不会计入职业一线队累计出场。':''}<br>培养与竞技数值、薪资条款和职业建议均为游戏内设定。</div><div class="modal-actions"><button class="btn outline" data-negotiate="${o.id}">争取更好的条款</button><button class="btn" data-sign="${o.id}">${o.kind==='promotion'?'接受晋升邀请':'选择这条发展路线'} ${icon('check',14)}</button></div>`,true);
